-- MGM starter schema. Review before production. Never store passwords or payment PINs here.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, referral_code text unique, created_at timestamptz not null default now());
create table if not exists public.tasks (id bigint generated by default as identity primary key, title text not null, description text not null default '', reward numeric(12,2) not null default 0 check (reward >= 0), is_active boolean not null default false, created_at timestamptz not null default now());
alter table public.profiles enable row level security;
alter table public.tasks enable row level security;
create policy "read own profile" on public.profiles for select to authenticated using (auth.uid() = id);
create policy "insert own profile" on public.profiles for insert to authenticated with check (auth.uid() = id);
create policy "update own profile" on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);
create policy "read active tasks" on public.tasks for select to authenticated using (is_active = true);
-- No wallet, payout, or admin policy is included: those need verified server-side authorization and transaction logic.
